<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/backup_step18.php';require_once __DIR__.'/config/deployment_step19.php';
$error=null;$success=null;$rows=[];try{$pdo=business_db();deployment_step19_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=deployment_step19_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$id=deployment_step19_register_release($pdo,(string)($_POST['version']??''),(string)($_POST['sha']??''),(string)($_POST['status']??'planned'),(string)($_POST['notes']??''),(int)$user['id']);$success='Release #'.$id.' registered.';}$s=$pdo->prepare("SELECT r.*,u.full_name deployed_by_name FROM deployment_releases r LEFT JOIN system_users u ON u.id=r.deployed_by WHERE r.organization_id=? ORDER BY r.id DESC LIMIT 100");$s->execute([$orgId]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Releases - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="deployment_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 19 • Release Registry</small></span></a><div class="os-top-actions"><a class="os-btn primary" href="deployment_center.php">Deployment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Production</div><nav class="os-nav"><a href="deployment_center.php"><i class="dot"></i>Deployment</a><a class="active" href="deployment_releases.php"><i class="dot"></i>Releases</a><a href="maintenance_center.php"><i class="dot"></i>Maintenance</a><a href="step19_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">RELEASE TRACEABILITY</div><h1>Know exactly which application version is planned, ready, deployed or rolled back.</h1><p>STEP 19 records release metadata only; it does not pretend a Git commit is deployed until you explicitly mark it. Production deployment requires production environment gates and a verified STEP 18 recovery point.</p></section><?php if($error):?><div class="pp-alert bad"><?= deployment_step19_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?= deployment_step19_h($success) ?></div><?php endif;?><section class="s10-grid"><article class="s10-card s10-span-5"><h2>Register Release</h2><form method="post"><input type="hidden" name="csrf" value="<?= deployment_step19_h(security_step17_csrf()) ?>"><label><b>Version label</b><input name="version" required placeholder="v1.0.0" style="width:100%;margin:6px 0 12px"></label><label><b>Git commit SHA</b><input name="sha" placeholder="optional 7–64 hex characters" style="width:100%;margin:6px 0 12px"></label><label><b>Status</b><select name="status" style="width:100%;margin:6px 0 12px"><option>planned</option><option>ready</option><option>deployed</option><option>rolled_back</option><option>failed</option></select></label><label><b>Notes</b><textarea name="notes" rows="4" style="width:100%;margin-top:6px"></textarea></label><button class="os-btn primary" style="margin-top:12px">Register Release</button></form></article><article class="s10-card s10-span-7"><h2>Release History</h2><div class="s10-list"><?php if(!$rows):?><div class="pp-alert">No release record yet. This is valid before the first cloud deployment.</div><?php endif;?><?php foreach($rows as $r):?><div class="s10-row"><div><b><?= deployment_step19_h($r['version_label']) ?> • <?= deployment_step19_h($r['release_code']) ?></b><small><?= deployment_step19_h(strtoupper($r['environment_code']).' • '.$r['release_status']) ?><?= $r['git_commit_sha']?' • '.deployment_step19_h(substr($r['git_commit_sha'],0,12)):'' ?><?= $r['deployed_at']?' • '.$r['deployed_at']:'' ?></small></div><span class="s10-badge <?= $r['release_status']==='deployed'?'':'warn' ?>"><?= deployment_step19_h(strtoupper($r['release_status'])) ?></span></div><?php endforeach;?></div></article></section></main></div></body></html>